import{_ as l,D as p,o as n,c as s,j as o,a as e,I as a,w as r,am as d}from"./chunks/framework.DXw8qDd0.js";const k=JSON.parse('{"title":"Codex 5 个实用技巧","description":"","frontmatter":{"title":"Codex 5 个实用技巧","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex 5 个实用技巧.md","filePath":"笔记/Codex/Codex 5 个实用技巧.md"}'),i={name:"笔记/Codex/Codex 5 个实用技巧.md"},_=d('<p>Codex 5 个实用技巧</p><ol><li>🧠 开启 Memory，让 Codex 记住你的工作习惯</li></ol><p>Memory 的价值不只是&quot;记住聊过什么&quot;，而是记住你反复验证过的做事方式。</p><p>比如你每次排查 Bug 都习惯结合代码和数据库一起查，开启 Memory 后，以后只需把 Bug 现象告诉它，它就会自动按这个路径排查。</p><p>💡 前提：你自己的提问方式要稳定可复用，它才能沉淀出有价值的习惯。</p><ol start="2"><li>📋 写好 AGENTS.md，固化项目规则</li></ol><p>在项目根目录创建 AGENTS.md，把技术栈、常用命令、禁止修改的目录、代码风格等写进去，Codex 每次启动都会读取。</p><p>这样可以避免它&quot;不知道怎么跑测试&quot;、&quot;随便改了不该改的文件&quot;等低级错误，团队使用时效果尤为显著。</p><ol start="3"><li>🔄 用 CLI 替代 MCP，更省资源和 Token</li></ol><p>MCP 会拉起大量后台线程，执行过程直接进入大模型上下文，导致 Token 消耗高、速度慢。</p><p>切换到 CLI 模式后： · 电脑资源占用更低 · Token 消耗明显减少 · 体感速度更快</p><p>以 Playwright 为例，截图、控制台输出等走结构化文件输出，比 MCP 更轻更高效。</p><ol start="4"><li>📝 先计划再执行，用&quot;四段式提示词&quot;</li></ol><p>不要直接让 Codex 改代码，先让它给计划：</p><p>目标：你要完成什么 上下文：相关文件、错误日志 约束：不能做什么 完成标准：怎样算完成</p><p>复杂任务尤其适用先读 → 先计划 → 再改 → 最后验证的节奏，大大减少&quot;改多了&quot;或&quot;改错了&quot;的情况。</p><ol start="5"><li>🔍 任务完成后让 Codex 做&quot;自审&quot;，而不是自己盯 diff</li></ol><p>每次 Codex 改完代码，不要自己一行行看 diff，而是让它先做一轮自查：</p><p>请自查刚才的改动： · 是否满足原始需求？ · 有没有改到无关的文件？ · 有没有潜在 bug 或回归风险？ · 缺不缺测试？</p><p>请按&quot;阻塞问题 / 非阻建议 / 验证结果&quot;三类输出。</p><p>这样做有两个好处： · 它能发现自己的错误，比你肉眼扫 diff 更全面 · 你可以把精力放在&quot;阻塞问题&quot;上，非阻塞的建议性问题让它自己处理</p>',21),c={id:"—-老金-freeman1266-·-2026-05-06-21-45",tabindex:"-1"},u=o("a",{class:"header-anchor",href:"#—-老金-freeman1266-·-2026-05-06-21-45","aria-label":'Permalink to "— [老金 (@freeman1266)](https://x.com/freeman1266/status/2052021919948693862) · 2026-05-06 21:45"'},"​",-1);function m(f,x,C,q,h,P){const t=p("VPNolebaseInlineLinkPreview");return n(),s("div",null,[_,o("h2",c,[e("— "),a(t,{href:"https://x.com/freeman1266/status/2052021919948693862",target:"_blank",rel:"noreferrer"},{default:r(()=>[e("老金 (@freeman1266)")]),_:1}),e(" · 2026-05-06 21:45 "),u]),o("blockquote",null,[o("p",null,[e("📎 "),a(t,{href:"/ocdsync/笔记/"},{default:r(()=>[e("📒 返回笔记索引")]),_:1})])])])}const N=l(i,[["render",m]]);export{k as __pageData,N as default};
